//! Layout registry (S6): the single source of truth for layout ids.
//!
//! Builtin layouts ship as JSON under `src/layouts/` (generated by
//! `scripts/generate-layouts.mjs`): 5 ANSI layouts plus ISO (105 keys)
//! and JIS (109 keys). Custom layouts arrive through the importer
//! (`layout_import`) and live in `AppConfig.custom_layouts`.
//!
//! Layout packs (HHKB, Alice, split) extend this registry later by
//! adding builtin ids here and JSON files under `src/layouts/`; no
//! other code needs to change.

use crate::profiles::layout_import::ImportedLayout;

/// Canonical builtin layout ids. Every validation site uses this list
/// (directly or through `is_valid_layout_id`); do not duplicate it.
pub const BUILTIN_LAYOUT_IDS: &[&str] = &[
    "fullsize-ansi",
    "tkl-ansi",
    "75-ansi",
    "65-ansi",
    "60-ansi",
    "fullsize-iso",
    "fullsize-jis",
];

pub fn is_builtin_layout_id(id: &str) -> bool {
    BUILTIN_LAYOUT_IDS.contains(&id)
}

/// Layout id format shared by builtin ids and imports: lowercase
/// letters, digits, hyphens; 1-64 chars; must start with a letter or
/// digit. Uppercase and other characters are rejected so ids stay
/// safe as file names and JSON keys.
pub fn is_valid_layout_id_format(id: &str) -> bool {
    if id.is_empty() || id.len() > 64 {
        return false;
    }
    let mut chars = id.chars();
    if !matches!(chars.next(), Some(c) if c.is_ascii_lowercase() || c.is_ascii_digit()) {
        return false;
    }
    chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
}

/// A layout id is valid when it is builtin or an imported custom
/// layout stored in the config.
pub fn is_valid_layout_id(id: &str, custom: &[ImportedLayout]) -> bool {
    is_builtin_layout_id(id) || custom.iter().any(|l| l.id == id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn builtin_ids_cover_ansi_iso_jis() {
        assert_eq!(BUILTIN_LAYOUT_IDS.len(), 7);
        for id in ["fullsize-ansi", "tkl-ansi", "75-ansi", "65-ansi", "60-ansi"] {
            assert!(is_builtin_layout_id(id), "{id} must be builtin");
        }
        assert!(is_builtin_layout_id("fullsize-iso"));
        assert!(is_builtin_layout_id("fullsize-jis"));
        assert!(!is_builtin_layout_id("fullsize-hhkb"));
    }

    #[test]
    fn id_format_rules() {
        assert!(is_valid_layout_id_format("my-layout-1"));
        assert!(is_valid_layout_id_format("a"));
        assert!(!is_valid_layout_id_format(""));
        assert!(!is_valid_layout_id_format("-abc"));
        assert!(!is_valid_layout_id_format("MyLayout"));
        assert!(!is_valid_layout_id_format("my_layout"));
        assert!(!is_valid_layout_id_format("my layout"));
        assert!(!is_valid_layout_id_format(&"a".repeat(65)));
        assert!(is_valid_layout_id_format(&"a".repeat(64)));
    }

    #[test]
    fn custom_ids_validate_only_when_stored() {
        let custom: Vec<ImportedLayout> = vec![];
        assert!(!is_valid_layout_id("my-layout", &custom));
        assert!(is_valid_layout_id("fullsize-iso", &custom));
    }
}
